const TYPEWRITER_HTML='<div style="margin:12px 0;padding:12px 16px;background:rgba(0,0,0,.28);border:1px solid rgba(124,108,240,.4);border-radius:10px;font-family:Consolas,monospace;font-size:13px;line-height:1.9">\n<style>\n@keyframes opg-tw{from{width:0}to{width:22ch}}\n@keyframes opg-caret{50%{border-color:transparent}}\n.opg-tw{display:inline-block;overflow:hidden;white-space:nowrap;max-width:100%;border-right:2px solid var(--opg-primary,#7c6cf0);animation:opg-tw 2.6s steps(22) .4s forwards,opg-caret .8s step-end infinite}\n</style>\n<span class="opg-tw">正在接入终端……信号校准中，请稍候。</span>\n</div>';
const TABS_HTML='<div style="margin:12px 0">\n<style>\n.opg-tabs input{display:none}\n.opg-tabs label{display:inline-block;padding:6px 16px;margin-right:4px;font-size:12px;cursor:pointer;border:1px solid rgba(124,108,240,.4);border-bottom:none;border-radius:8px 8px 0 0;opacity:.6;user-select:none}\n.opg-tabs input:checked+label{opacity:1;color:var(--opg-accent,#e8c47c);border-color:var(--opg-accent,#e8c47c)}\n.opg-tabs .opg-tab-pane{display:none;padding:12px 14px;border:1px solid rgba(124,108,240,.4);border-radius:0 8px 8px 8px;font-size:13px;line-height:1.8}\n.opg-tabs input:checked~.opg-tab-pane{display:none}\n#opg-tab1:checked~.opg-pane1,#opg-tab2:checked~.opg-pane2,#opg-tab3:checked~.opg-pane3{display:block}\n</style>\n<div class="opg-tabs">\n<input type="radio" name="opg-tabs" id="opg-tab1" checked><label for="opg-tab1">📖 简介</label>\n<input type="radio" name="opg-tabs" id="opg-tab2"><label for="opg-tab2">🎭 角色</label>\n<input type="radio" name="opg-tabs" id="opg-tab3"><label for="opg-tab3">📜 规则</label>\n<div class="opg-tab-pane opg-pane1">第一个标签页的内容，写世界观简介……</div>\n<div class="opg-tab-pane opg-pane2">第二个标签页的内容，写角色介绍……</div>\n<div class="opg-tab-pane opg-pane3">第三个标签页的内容，写游玩规则……</div>\n</div>\n</div>';
