const CAL_HTML='<div class="opg-cal">\n<style>\n.opg-cal{display:flex;margin:12px 0;background:rgba(255,255,255,.05);border:1px solid rgba(124,108,240,.4);border-radius:12px;overflow:hidden}\n.opg-cal-date{flex-shrink:0;width:78px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;background:linear-gradient(165deg,var(--opg-primary,#7c6cf0),var(--opg-accent,#453a75));color:#fff;padding:14px 8px}\n.opg-cal-mo{font-size:10px;letter-spacing:3px;opacity:.85}\n.opg-cal-day{font-size:30px;font-weight:700;line-height:1.15;font-variant-numeric:tabular-nums}\n.opg-cal-wd{font-size:10px;opacity:.8}\n.opg-cal-list{flex:1;min-width:0;padding:11px 14px;display:flex;flex-direction:column;justify-content:center;gap:7px;font-size:12.5px;line-height:1.55}\n.opg-cal-ev{display:flex;gap:9px;align-items:baseline}\n.opg-cal-tm{font-family:"JetBrains Mono",Consolas,monospace;font-size:11px;opacity:.55;flex-shrink:0}\n</style>\n<div class="opg-cal-date"><span class="opg-cal-mo">SEP</span><span class="opg-cal-day">01</span><span class="opg-cal-wd">星期二</span></div>\n<div class="opg-cal-list">\n<div class="opg-cal-ev"><span class="opg-cal-tm">08:00</span><span>开学典礼 · 大礼堂</span></div>\n<div class="opg-cal-ev"><span class="opg-cal-tm">15:30</span><span>社团招新 · 中庭</span></div>\n<div class="opg-cal-ev"><span class="opg-cal-tm">19:00</span><span>天台 · 与{{char}}有约</span></div>\n</div>\n</div>';
